"""SQLAlchemy engine, session helpers and the declarative base."""
from collections.abc import Iterator
from contextlib import contextmanager
from functools import lru_cache
from uuid import UUID

from sqlalchemy import Engine, MetaData, create_engine, text
from sqlalchemy.orm import DeclarativeBase, Session, sessionmaker

from app.core.config import get_settings

# Stable constraint names keep autogenerated migrations reproducible.
_NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_N_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    """Base class of every model."""

    metadata = MetaData(naming_convention=_NAMING_CONVENTION)


@lru_cache
def get_engine() -> Engine:
    """Return the process-wide engine.

    Sync handlers run on a thread pool of up to 40 threads, but each holds a connection only briefly,
    so 15 connections are plenty and stay well inside Postgres's default limit of 100.
    """
    return create_engine(
        get_settings().database_url.get_secret_value(),
        pool_size=5,
        max_overflow=10,
        pool_timeout=10,
        pool_pre_ping=True,
        connect_args={"connect_timeout": 5},
    )


@lru_cache
def _session_factory() -> sessionmaker[Session]:
    return sessionmaker(bind=get_engine(), expire_on_commit=False)


def get_db() -> Iterator[Session]:
    """FastAPI dependency yielding a session. Handlers commit explicitly."""
    with _session_factory()() as session:
        yield session


@contextmanager
def session_scope() -> Iterator[Session]:
    """Run a block in one transaction, committing on success and rolling back on any error."""
    with _session_factory()() as session, session.begin():
        yield session


def ping_database() -> bool:
    """Run a real `SELECT 1`, so the health endpoint reports what the database actually does."""
    try:
        with get_engine().connect() as connection:
            connection.execute(text("SELECT 1"))
    except Exception:  # noqa: BLE001  any failure here simply means the database is unhealthy
        return False
    return True


def is_uuid(value: str) -> bool:
    """Check a client-supplied id first, because Postgres raises an error on a malformed uuid."""
    try:
        UUID(value)
    except ValueError:
        return False
    return True
